const fs = require("node:fs");
const path = require("node:path");

describe("browser ECMAScript module", () => {
  const modulePath = path.resolve(__dirname, "..", "lib", "service-hub.mjs");
  let source;

  beforeAll(() => {
    source = fs.readFileSync(modulePath, "utf8");
  });

  it("is a generated artifact", () => {
    expect(source).toContain(
      "Generated by `npm run build` from src/service-hub.mjs",
    );
  });

  it("keeps event-kit as its only external module", () => {
    const imports = [...source.matchAll(/\bfrom\s+["']([^"']+)["']/g)].map(
      (match) => match[1],
    );

    expect(imports).toEqual(["@lumine-code/event-kit"]);
  });

  it("contains no CommonJS or Node runtime dependency", () => {
    expect(source).not.toMatch(/\brequire\s*\(/);
    expect(source).not.toMatch(/["']node:/);
    expect(source).not.toMatch(/\b(?:__dirname|__filename|process\.)/);
  });
});
